from pathlib import Path
import base64, zlib, subprocess, sys

root = Path(sys.argv[1]).resolve()
PATCH_B64 = ""
patch = zlib.decompress(base64.b64decode(PATCH_B64))
subprocess.run(["git", "-C", str(root), "apply", "--whitespace=nowarn", "-"], input=patch, check=True)
print("PKVault V8 alpha37 Pokédollar bank + fan-game dex corrections applied")
